from collections import deque, defaultdict

def comps_region(arr, color_pred, rows, cols, conn=4):
    coords={(r,c) for r in rows for c in cols if color_pred(arr[r][c])}
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    if conn==8: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
    out=[]
    while coords:
        p=coords.pop(); q=[p]; comp={p}
        while q:
            r,c=q.pop()
            for dr,dc in dirs:
                np=(r+dr,c+dc)
                if np in coords:
                    coords.remove(np); comp.add(np); q.append(np)
        out.append(comp)
    return sorted(out,key=lambda co:min(co))

